```ts
function applyPattern(target: string, match: string | undefined): string {
  if (match === undefined) return target;
  return target.split("*").join(match);
}

function resolveTarget(
  target: ExportsField | null,
  conditions: string[],
  match: string | undefined
): string | undefined {
  if (typeof target === "string") {
    const value = applyPattern(target, match);
    return value.startsWith("./") ? value : undefined;
  }
  if (Array.isArray(target)) {
    for (const entry of target) {
      const resolved = resolveTarget(entry, conditions, match);
      if (resolved !== undefined) return resolved;
    }
    return undefined;
  }
  if (target && typeof target === "object") {
    for (const key of Object.keys(target)) {
      if (key === "default" || conditions.includes(key)) {
        const resolved = resolveTarget(target[key], conditions, match);
        if (resolved !== undefined) return resolved;
      }
    }
  }
  return undefined;
}
```

resolveExports:

```ts
function resolveExports(
  exportsField: ExportsField,
  subpath: string,
  conditions: string[]
): string | undefined {
  if (typeof exportsField === "string" || Array.isArray(exportsField)) {
    return subpath === "." ? resolveTarget(exportsField, conditions, undefined) : undefined;
  }
  if (!exportsField || typeof exportsField !== "object") return undefined;

  const keys = Object.keys(exportsField);
  const allSubpathKeys = keys.every((key) => key.startsWith("."));

  if (!allSubpathKeys) {
    // conditional main
    return subpath === "." ? resolveTarget(exportsField, conditions, undefined) : undefined;
  }

  if (Object.prototype.hasOwnProperty.call(exportsField, subpath)) {
    return resolveTarget(exportsField[subpath], conditions, undefined);
  }

  let best: { match: string; target: string } | undefined;
  for (const key of keys) {
    const star = key.indexOf("*");
    if (star === -1) continue;
    const prefix = key.slice(0, star);
    const suffix = key.slice(star + 1);
    if (
      subpath.length >= prefix.length + suffix.length &&
      subpath.startsWith(prefix) &&
      subpath.endsWith(suffix)
    ) {
      const match = subpath.slice(prefix.length, subpath.length - suffix.length);
      const resolved = resolveTarget(exportsField[key], conditions, match);
      if (resolved !== undefined && (best === undefined || prefix.length > /* best prefix len */ 0)) {
        best = { match, target: resolved };
      }
      if (resolved !== undefined) return resolved;
    }
  }
  return best?.target;
}
```

